{
 "schema": "capability-registry/1",
 "capabilities": {
  "text.probe": {
   "kind": "tool",
   "version": "1.0.0",
   "impl": {
    "runtime": "python3",
    "entry": "${SKILL}/scripts/cap.py",
    "args": [
     "probe",
     "{pdf}"
    ]
   },
   "config_schema": {
    "pdf": {
     "type": "path",
     "required": true
    }
   },
   "contract": {
    "outputs": [
     "route",
     "pages",
     "fonts",
     "images"
    ],
    "exit": {
     "0": "ok"
    }
   },
   "owner": "standard-element-extraction",
   "conformance": [
    "HJ84-2016.pdf -> route=OCR",
    "HJ535-2009.txt -> route=PDF_TEXT"
   ]
  },
  "ocr.engine": {
   "kind": "tool",
   "version": "0.1.0",
   "impl": {
    "runtime": "bin",
    "entry": "hj84-2016/out/ocr",
    "args": [
     "{pdf}",
     "{outdir}",
     "{dpi}"
    ]
   },
   "config_schema": {
    "engine": {
     "type": "enum",
     "values": [
      "apple-vision",
      "user-model",
      "fallback-none"
     ],
     "default": "apple-vision"
    },
    "dpi": {
     "type": "int",
     "default": 600,
     "range": [
      150,
      1200
     ]
    },
    "endpoint": {
     "type": "string",
     "required": false,
     "when": "engine==user-model"
    }
   },
   "contract": {
    "outputs": [
     "page-*.png",
     "page-*.tsv"
    ],
    "exit": {
     "0": "ok"
    }
   },
   "fallback": [
    "user-model",
    "apple-vision",
    "fallback-none"
   ],
   "owner": "输入侧（用户 OCR 模型）",
   "conformance": [
    "14/14 页出图",
    "逐页 tsv 非空",
    "20 张 golden 字串全中"
   ]
  },
  "clause.split": {
   "kind": "tool",
   "version": "1.0.0",
   "impl": {
    "runtime": "python3",
    "entry": "${SKILL}/scripts/clause_split.py",
    "args": [
     "--text",
     "{text}",
     "--out",
     "{out}"
    ]
   },
   "config_schema": {
    "text": {
     "type": "path"
    },
    "out": {
     "type": "path"
    },
    "min_level": {
     "type": "int",
     "default": 1
    }
   },
   "contract": {
    "outputs": [
     "clauses",
     "toc",
     "n"
    ],
    "precondition": "text.quality.route==PDF_TEXT"
   },
   "owner": "standard-element-extraction",
   "conformance": [
    "干净文本 n=89 且 toc 非空"
   ]
  },
  "audit.lint": {
   "kind": "tool",
   "version": "1.0.0",
   "impl": {
    "runtime": "python3",
    "entry": "${SKILL}/scripts/cap.py",
    "args": [
     "lint",
     "--ses",
     "{ses}"
    ]
   },
   "config_schema": {
    "ses": {
     "type": "path",
     "required": true
    }
   },
   "contract": {
    "outputs": [
     "errors",
     "warnings",
     "ok"
    ],
    "exit": {
     "0": "ok",
     "1": "blocking"
    }
   },
   "owner": "standard-element-extraction",
   "conformance": [
    "规则卡齐全时 ok=true"
   ]
  },
  "audit.ontology": {
   "kind": "tool",
   "version": "1.0.0",
   "impl": {
    "runtime": "python3",
