     "--ses",
     "{ses}"
    ]
   },
   "config_schema": {
    "ses": {
     "type": "path"
    },
    "graph": {
     "type": "path",
     "required": false
    }
   },
   "contract": {
    "outputs": [
     "ERROR",
     "WARN"
    ]
   },
   "owner": "standard-element-extraction",
   "status": "OK",
   "conformance": []
  },
  "llm.semantic": {
   "kind": "llm",
   "version": "1.0.0",
   "impl": {
    "runtime": "agent",
    "skill": "standard-element-extraction",
    "schema_ref": "references/standard-element-schema.md"
   },
